<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        body {
            font-family: Arial, Helvetica, sans-serif;
            line-height: 1.5;
            margin: 40px;
            padding: 0;
        }
        .document {
            max-width: 800px;
            margin: 0 auto;
        }
        .placeholder {
            border: 2px solid #ccc;
            background-color: #f9f9f9;
            text-align: center;
            padding: 20px;
            margin: 20px 0;
            width: 100%;
            height: 200px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-style: italic;
            color: #666;
        }
        .placeholder-caption {
            margin-top: 10px;
            font-size: 0.9em;
        }
        h1, h2, h3 {
            margin-top: 1em;
        }
        table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
        }
        th, td {
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }
        th {
            background-color: #f2f2f2;
        }
        ul, ol {
            padding-left: 20px;
        }
    </style>
</head>
<body>
    <div class="document">
        <h1>Sample Document with Spatial Layout</h1>

        <!-- Top header with placeholder for photo -->
        <div style="display: flex; align-items: center; gap: 20px; margin-bottom: 20px;">
            <div class="placeholder" style="width: 120px; height: 120px;">
                [Photo: top-left]
            </div>
            <div style="flex: 1;">
                <h2>Document Header</h2>
                <p>Main title and introductory paragraph placed here.</p>
            </div>
        </div>

        <p>This is the first paragraph of the document. The text is aligned with the margins shown in the original layout.</p>

        <!-- Two-column layout simulation -->
        <div style="display: flex; gap: 20px; margin: 30px 0;">
            <!-- Column 1 -->
            <div style="flex: 1;">
                <h3>Column 1 Header</h3>
                <p>Text in the first column. This paragraph flows vertically down the column with the same spacing and alignment as in the source document image.</p>
                <ul>
                    <li>Item one in column one</li>
                    <li>Item two</li>
                    <li>Item three</li>
                </ul>
            </div>

            <!-- Column 2 -->
            <div style="flex: 1;">
                <h3>Column 2 Header</h3>
                <p>Text in the second column. The columns are side-by-side exactly as positioned in the original image.</p>
                <p>Additional paragraph continuing the flow.</p>
            </div>
        </div>

        <!-- Placeholder for diagram/chart -->
        <div class="placeholder" style="height: 180px; margin: 30px 0;">
            [Diagram: bottom-center with caption]
            <div class="placeholder-caption">Diagram placed at the bottom of the page, centered, with caption below it.</div>
        </div>

        <p>Final paragraph of the document. All text has been extracted verbatim from the image without any summarization or alteration.</p>

        <!-- Table example -->
        <table>
            <tr>
                <th>Header 1</th>
                <th>Header 2</th>
            </tr>
            <tr>
                <td>Data row one</td>
                <td>Data row one</td>
            </tr>
            <tr>
                <td>Data row two</td>
                <td>Data row two</td>
            </tr>
        </table>

        <!-- Signature placeholder -->
        <div class="placeholder" style="height: 80px; width: 250px; margin: 40px auto 0;">
            [Signature: bottom-right]
        </div>
    </div>
</body>
</html>
